def run(env):
    out = {}
    n_questions = len(env.questions)
    samples_per_q = env.budget // n_questions

    # Topics where verifier score is reliable
    score_based_topics = {'combinatorics', 'number_theory'}

    for q in env.questions:
        qid = q["id"]
        topic = q["topic"]
        answer_info = {}  # answer -> {'count': int, 'total_score': float}

        # Sample across all variants
        for i in range(samples_per_q):
            variant = i % env.n_variants
            answer, score = env.sample(qid, variant)

            if answer not in answer_info:
                answer_info[answer] = {'count': 0, 'total_score': 0.0}

            answer_info[answer]['count'] += 1
            answer_info[answer]['total_score'] += score

        # Choose strategy based on topic
        if topic in score_based_topics:
            # Use verifier score for reliable topics
            best_answer = max(answer_info, key=lambda a: answer_info[a]['total_score'])
        else:
            # Use frequency (majority vote) for less reliable topics
            best_answer = max(answer_info, key=lambda a: answer_info[a]['count'])

        out[qid] = best_answer

    env.submit(out)

